css:
.cf { font-size: 10.5px; }
.cf .ar { font-family: "Noto Naskh Arabic", "Tahoma", sans-serif; direction: rtl; unicode-bidi: embed; color: #444; margin-left: 4px; }
.cf-head { width: 100%; margin-bottom: 6px; }
.cf-head .title { font-size: 15px; font-weight: 700; color: #0B3D5C; text-align: center; border-bottom: 2px solid #F2A900; padding: 4px 0 6px; }
.cf table.cf-grid, .cf table.cf-list { width: 100%; border-collapse: collapse; margin-bottom: 6px; }
.cf .cf-grid th, .cf .cf-grid td, .cf .cf-list th, .cf .cf-list td { border: 1px solid #b8c6d0; padding: 3px 5px; vertical-align: top; }
.cf .cf-grid th { background: #EAF1F6; width: 20%; text-align: left; font-weight: 600; }
.cf .cf-list th { background: #0B3D5C; color: #fff; font-weight: 600; text-align: left; }
.cf .cf-list th .ar { color: #dfe8ee; }
.cf .n { text-align: right; }
.cf .c { text-align: center; font-size: 13px; }
.cf .sec { background: #EAF1F6; color: #0B3D5C; font-weight: 700; padding: 3px 6px; margin: 8px 0 3px; border-left: 4px solid #F2A900; }
.cf .note { border: 1px dashed #b8c6d0; padding: 4px 6px; margin-bottom: 6px; }
.cf .result { padding: 6px; font-weight: 700; font-size: 12px; margin: 6px 0; text-align: center; }
.cf .result.ok { background: #e3f4e8; color: #1e6b37; }
.cf .result.bad { background: #fbe4e4; color: #9b1c1c; }
.cf .sign td { height: 22px; }

.cf-head .sub { font-size: 11px; font-weight: 400; color: #5A6B78; }
.cf th .ar, .cf .sec .ar { display: block; margin-left: 0; font-weight: 400; font-size: 9.5px; text-align: left; }
.cf .sec { font-size: 11px; }
.cf td .ar { display: inline-block; }
